// Merch Store catalog (near.com/nearmerch.com-style grid). Every item is
// priced at a flat $30 USD, converted to its NEAR-equivalent at the same
// mock NEAR/USD rate used everywhere else in the game, so the displayed
// NEAR price always tracks SWAP_ASSETS without needing to be hardcoded.
const MERCH_USD_PRICE = 30;
const MERCH_ITEMS = [
  { id: 'tee_intents', name: 'NEAR Intents Long Sleeve', category: 'Apparel', img: TSHIRT_INTENTS_IMG },
  { id: 'bucket_hat', name: 'near Bucket Hat', category: 'Accessories', img: BUCKET_HAT_IMG },
  { id: 'tee_legion', name: 'NEAR Legion Tee', category: 'Apparel', img: TSHIRT_LEGION_IMG },
  { id: 'bottle_legion', name: 'NEAR Legion Water Bottle', category: 'Accessories', img: BOTTLE_LEGION_IMG },
];
function merchPriceNear() {
  const near = SWAP_ASSETS.find(a => a.id === 'NEAR');
  return MERCH_USD_PRICE / near.usd;
}
// Generic USD → NEAR converter using the same mock NEAR/USD rate, so any
// other USD-denominated price in the game (e.g. IronClaw plans) tracks
// SWAP_ASSETS consistently instead of hardcoding its own rate.
function usdToNear(usd) {
  const near = SWAP_ASSETS.find(a => a.id === 'NEAR');
  return usd / near.usd;
}
