  // deliberately independent of WHY they ended up on Home (a specific
  // code path being fixed elsewhere, a genuine edge case, anything) -
  // it's a general safety net that catches all of them the same way.
  const [showRejoinPrompt, setShowRejoinPrompt] = useState(false);
  useEffect(() => {
    if (screen !== 'home') { setShowRejoinPrompt(false); return; }
    try {
      const hasRoom = !!(localStorage.getItem('nearSaboteurRoomCode') && localStorage.getItem('nearSaboteurPlayerToken'));
      const hasPool = !!(localStorage.getItem('nearSaboteurPoolId') && localStorage.getItem('nearSaboteurPlayerToken'));
      setShowRejoinPrompt(hasRoom || hasPool);
    } catch (e) { /* localStorage unavailable */ }
  }, [screen]);
  const [playerName, setPlayerName] = useState(''); // [PER-PLAYER]
  const [playerAvatarId, setPlayerAvatarId] = useState(() => AVATARS[Math.floor(Math.random() * AVATARS.length)].id); // [PER-PLAYER]

